const state = items[0].json;

if (!state.payload || !state.agent) {
  throw new Error("Invalid envelope: payload or agent missing");
}

state.registry = state.payload.registry || {};
state.policies = state.policies || {};
state.plan = state.plan || {};

state.plan.steps = [];
state.authorization = state.authorization || {};

return [{ json: state }];

const state = items[0].json;

const ref = state.agent.detected_usecase;
const usecase = state.registry.usecases?.[ref];

if (!usecase) {
  throw new Error(`Unknown certified usecase: ${ref}`);
}

// Validation minimale
if (usecase.inputs_required) {
  for (const key of usecase.inputs_required) {
    if (!(key in state.payload.input)) {
      throw new Error(`Missing required input: ${key}`);
    }
  }
}

// Compilation deterministe
state.plan.steps = usecase.steps_template.map(step => ({
  tool_ref: step.tool_ref,
  args: step.args
}));

state.authorization = {
  mode: "preapproved",
  usecase_ref: ref,
  version: usecase.version
};

return [{ json: state }];

