    {
      role: "system",
      content: "You are a planning agent. Produce ONLY tool steps."
    },
    {
      role: "user",
      content: state.payload.intent
    }
  ]
};

return [{ json: state }];

const state = items[0].json;
const output = state.llm_output || state.output || state.data || {};

if (!Array.isArray(output.steps)) {
  throw new Error("LLM output invalid: steps[] missing");
}

state.plan.steps = output.steps.map(step => ({
  tool_ref: step.tool_ref || step.ref || step.tool,
  args: step.args || step.params || {}
}));

state.authorization = {
  mode: "human_required"
};

return [{ json: state }];

const state = items[0].json;

state.payload = state.payload || {};
state.payload.context = state.payload.context || {};

const planSteps = state.plan?.steps;
const planContract = {
  contract_version: state.plan?.contract_version || '1.0',
  session_id: state.execution?.session_id || state.payload?.context?.memory?.session_id || 'unknown',
  status: state.plan?.status || 'proposed',
  plan: planSteps
};

function validatePlanSchema(plan) {
  const errors = [];
  if (!plan || typeof plan !== 'object') {
    errors.push('Plan must be an object');
    return errors;
  }
  if (typeof plan.contract_version !== 'string' || !plan.contract_version) {
    errors.push('contract_version must be a non-empty string');
  }
  if (typeof plan.session_id !== 'string' || !plan.session_id) {
    errors.push('session_id must be a non-empty string');
  }
  if (typeof plan.status !== 'string' || !plan.status) {
    errors.push('status must be a non-empty string');
  }
  if (!Array.isArray(plan.plan)) {
    errors.push('plan must be an array');
  } else {
    plan.plan.forEach((step, index) => {
      if (!step || typeof step !== 'object') {
        errors.push(`plan[${index}] must be an object`);
      }
    });
  }
  return errors;
}

function isOutputReference(value) {
  if (typeof value === 'string') {
    if (value.match(/\$\.plan\[\d+\]\.outputs\./)) return true;
    if (value.match(/\{\{.*\$step\[\d+\]\.outputs\./)) return true;
    if (value.match(/step\[\d+\]\.outputs\./)) return true;
  }

  if (typeof value === 'object' && value !== null) {
    if (value.$ref && typeof value.$ref === 'string') {
      return /step\[\d+\]\.outputs\./.test(value.$ref);
    }
  }

  return false;
}

function isLiteralValue(value) {
  if (value === undefined) return false;
  if (isOutputReference(value)) return false;
  if (Array.isArray(value)) {
    return value.every((item) => isLiteralValue(item));
  }
  if (typeof value === 'object' && value !== null) {
    return Object.values(value).every((nested) => isLiteralValue(nested));
  }
  return true;
}

function extractStepIndex(reference) {
  const match = reference.match(/\[(\d+)\]/);
  return match ? parseInt(match[1], 10) : -1;
}

function validateStepInputs(step, stepIndex, allSteps) {
  const errors = [];

  if (!step.inputs || step.inputs === null) {
    return errors;
  }

  if (typeof step.inputs !== 'object') {
    errors.push(`Step ${stepIndex}: inputs must be an object, got ${typeof step.inputs}`);
    return errors;
  }

  for (const [inputKey, inputValue] of Object.entries(step.inputs)) {
    if (isLiteralValue(inputValue)) {
      continue;
    }

    if (isOutputReference(inputValue)) {
      const referencedStepIndex = extractStepIndex(
        typeof inputValue === 'string' ? inputValue : inputValue.$ref
      );

      if (referencedStepIndex < 0) {
        errors.push(`Step ${stepIndex}, input "${inputKey}": Invalid output reference format`);
      } else if (referencedStepIndex >= allSteps.length) {
        errors.push(
          `Step ${stepIndex}, input "${inputKey}": References step ${referencedStepIndex} which does not exist in the plan`
        );
      } else if (referencedStepIndex >= stepIndex) {
        errors.push(
          `Step ${stepIndex}, input "${inputKey}": References step ${referencedStepIndex} which is not a precedent step (must reference earlier steps only)`
        );
      }
      continue;
    }

    errors.push(
      `Step ${stepIndex}, input "${inputKey}": Input value must be either a literal value OR a reference to a precedent step's output`
    );
  }

  return errors;
}

function validateStepPlan(plan) {
  const errors = [];

  if (!plan || !Array.isArray(plan)) {
    errors.push('Plan must be an array');
    return errors;
  }

  plan.forEach((step, index) => {
    const stepErrors = validateStepInputs(step, index, plan);
    errors.push(...stepErrors);
  });

  return errors;
}

const schemaErrors = validatePlanSchema(planContract);
const stepErrors = validateStepPlan(planContract.plan);

const validationSummary = {
  plan_schema: {
    valid: schemaErrors.length === 0,
    errors: schemaErrors
  },
  step_inputs: {
    valid: stepErrors.length === 0,
    errors: stepErrors
  }
};

state.payload.context.validation = validationSummary;

if (!validationSummary.plan_schema.valid || !validationSummary.step_inputs.valid) {
  state.payload.context.require_human_validation = true;
  state.payload.context.human = state.payload.context.human || {};
  state.payload.context.human.validation_errors = [...schemaErrors, ...stepErrors].slice(0, 5);
  state.authorization = {
    ...state.authorization,
    mode: 'human_required'
  };
} else {
  state.authorization = {
    ...state.authorization,
    mode: 'auto_approved'
  };
}

return [{ json: state }];
